338		if err := st.Close(); err != nil {
339			t.Fatal(err)
340		}
341	
342		st2, err := app.Open(dbPath)
343		if err != nil {
344			t.Fatal(err)
345		}
346		defer func() { _ = st2.Close() }()
347		h2 := NewHandler(st2)
348		r := httptest.NewRequest(http.MethodPost, "/v1/documents/doc/changes/query", strings.NewReader(`{"deviceId":"dev-1","ids":["c1","c2","nope"]}`))
349		r.Header.Set("Content-Type", "application/json")
350		w := httptest.NewRecorder()
351		h2.ServeHTTP(w, r)
352		if w.Code != http.StatusOK {
353			t.Fatalf("after restart = %d %s", w.Code, w.Body.String())
354		}
355		if w.Body.String() != body {
356			t.Fatalf("body changed across restart:\nbefore %q\nafter  %q", body, w.Body.String())
357		}
358	}
