165			t.Fatalf("counter state = %q", got)
166		}
167		if got := crdtStateBody(t, h, "doc-gset"); got != `{"type":"gset","value":["x"]}`+"\n" {
168			t.Fatalf("gset state = %q", got)
169		}
170	}
171	
172	// Device and permission gating is decided before any CRDT content is read:
173	// an unregistered device gets 404 and a revoked device 403 even when the
174	// batch would otherwise lose to type fixation, and a malformed request is a
175	// 400 even from an unregistered device. None of the answers reveal the type
176	// or the state.
177	func TestCRDTOpsGatingPrecedesTypeAndStateChecks(t *testing.T) {
178		h, _ := newTestHandler(t)
179		registerDevice(t, h, "dev-1")
180		registerDevice(t, h, "dev-2")
181	
182		if w := submitCRDT(t, h, "doc", crdtCounterBody("dev-1", crdtCounterOp("c1", 7))); w.Code != http.StatusOK {
183			t.Fatal(w.Body.String())
184		}
185		w, _ := postJSON(t, h, "/v1/documents/doc/permissions",
186			map[string]any{"deviceId": "dev-2", "action": "revoke"})
187		if w.Code != http.StatusOK {
188			t.Fatal(w.Body.String())
189		}
190	
191		// Shape validation beats the device lookup: malformed JSON and a missing
192		// field from an unregistered device are 400, not 404.
193		w, _ = postJSON(t, h, "/v1/documents/doc/crdt/ops", `{"deviceId":"ghost","type":`)
194		if w.Code != http.StatusBadRequest {
195			t.Fatalf("malformed from ghost = %d, want 400", w.Code)
196		}
197		w, _ = postJSON(t, h, "/v1/documents/doc/crdt/ops", `{"deviceId":"ghost","ops":[{"id":"a","value":1}]}`)
198		if w.Code != http.StatusBadRequest {
199			t.Fatalf("missing type from ghost = %d, want 400", w.Code)
200		}
201	
202		// An unregistered device is 404 even though the declared type would lose
203		// to the fixed counter type.
204		w = submitCRDT(t, h, "doc", crdtGSetBody("ghost", crdtGSetOp("g1", "x")))
205		if w.Code != http.StatusNotFound {
206			t.Fatalf("ghost with wrong type = %d, want 404", w.Code)
207		}
208		assertJSONError(t, w)
209	
210		// A revoked device is 403 on any batch, type-conforming or not.
211		w = submitCRDT(t, h, "doc", crdtGSetBody("dev-2", crdtGSetOp("g1", "x")))
212		if w.Code != http.StatusForbidden {
213			t.Fatalf("revoked with wrong type = %d, want 403", w.Code)
214		}
215		assertJSONError(t, w)
216		w = submitCRDT(t, h, "doc", crdtCounterBody("dev-2", crdtCounterOp("c2", 1)))
217		if w.Code != http.StatusForbidden {
218			t.Fatalf("revoked with right type = %d, want 403", w.Code)
219		}
220	
221		// Nothing moved.
222		if got := crdtStateBody(t, h, "doc"); got != `{"type":"counter","value":7}`+"\n" {
223			t.Fatalf("state after gated rejections = %q", got)
224		}
225	}
226	
227	// A rejected batch writes nothing: neither a 400 (one invalid op) nor a 409
228	// (one conflicting or regressing op) records the batch's valid operations.
229	func TestCRDTOpsBatchAtomicityOn400And409(t *testing.T) {
230		h, _ := newTestHandler(t)
231		registerDevice(t, h, "dev-1")
232	
233		seed := func(doc string) {
234			t.Helper()
235			if w := submitCRDT(t, h, doc, crdtCounterBody("dev-1", crdtCounterOp("seed", 5))); w.Code != http.StatusOK {
236				t.Fatalf("seed %s: %s", doc, w.Body.String())
237			}
238		}
239	
240		// 409: the batch pairs a valid new op with a conflicting existing id.
241		seed("doc-conflict")
242		w := submitCRDT(t, h, "doc-conflict", crdtCounterBody("dev-1",
243			crdtCounterOp("new-1", 6), crdtCounterOp("seed", 9)))
244		if w.Code != http.StatusConflict {
245			t.Fatalf("conflicting batch = %d, want 409", w.Code)
246		}
247		if got := crdtStateBody(t, h, "doc-conflict"); got != `{"type":"counter","value":5}`+"\n" {
248			t.Fatalf("state after conflicting batch = %q", got)
249		}
250		// The valid op of the rejected batch was not recorded.
251		w = submitCRDT(t, h, "doc-conflict", crdtCounterBody("dev-1", crdtCounterOp("new-1", 6)))
252		if _, created := postJSONResult(t, w); !created {
253			t.Fatal("new-1 must still be a fresh id after the rejected batch")
254		}
255	
256		// 409: the batch pairs a valid advance with a regressing contribution.
257		seed("doc-regress")
258		w = submitCRDT(t, h, "doc-regress", crdtCounterBody("dev-1",
259			crdtCounterOp("up", 7), crdtCounterOp("down", 3)))
260		if w.Code != http.StatusConflict {
261			t.Fatalf("regressing batch = %d, want 409", w.Code)
262		}
263		if got := crdtStateBody(t, h, "doc-regress"); got != `{"type":"counter","value":5}`+"\n" {
264			t.Fatalf("state after regressing batch = %q", got)
265		}
266		w = submitCRDT(t, h, "doc-regress", crdtCounterBody("dev-1", crdtCounterOp("up", 7)))
267		if _, created := postJSONResult(t, w); !created {
268			t.Fatal("up must still be a fresh id after the rejected batch")
269		}
270	
271		// 400: the batch pairs a valid op with an invalid one.
272		seed("doc-invalid")
273		w = submitCRDT(t, h, "doc-invalid", `{"deviceId":"dev-1","type":"counter","ops":[{"id":"ok","value":6},{"id":"bad","value":-1}]}`)
274		if w.Code != http.StatusBadRequest {
275			t.Fatalf("invalid batch = %d, want 400", w.Code)
276		}
277		if got := crdtStateBody(t, h, "doc-invalid"); got != `{"type":"counter","value":5}`+"\n" {
278			t.Fatalf("state after invalid batch = %q", got)
279		}
280		w = submitCRDT(t, h, "doc-invalid", crdtCounterBody("dev-1", crdtCounterOp("ok", 6)))
281		if _, created := postJSONResult(t, w); !created {
282			t.Fatal("ok must still be a fresh id after the 400 batch")
283		}
284	}
285	
286	// At every moment the session-scoped read and the document-level read are
287	// byte-for-byte identical, for all four CRDT types.
288	func TestCRDTSessionAndDocumentStateIdenticalForAllTypes(t *testing.T) {
289		h, _ := newTestHandler(t)
290		createSessionViaHTTP(t, h, "dev-1", "sess")
291		registerDevice(t, h, "dev-2")
292	
293		assertSame := func(t *testing.T, doc string) {
294			t.Helper()
295			docRec := httptest.NewRecorder()
296			h.ServeHTTP(docRec, httptest.NewRequest(http.MethodGet, "/v1/documents/"+doc+"/crdt/state", nil))
297			sessRec := httptest.NewRecorder()
298			h.ServeHTTP(sessRec, httptest.NewRequest(http.MethodGet, sessionCRDTStatePath("sess", doc), nil))
299			if docRec.Code != sessRec.Code || docRec.Body.String() != sessRec.Body.String() {
300				t.Fatalf("doc %s: document = %d %q, session = %d %q",
301					doc, docRec.Code, docRec.Body.String(), sessRec.Code, sessRec.Body.String())
302			}
303		}
304	
305		steps := []struct {
306			doc  string
307			body map[string]any
308		}{
309			{"doc-counter", crdtCounterBody("dev-1", crdtCounterOp("c1", 4))},
310			{"doc-counter", crdtCounterBody("dev-2", crdtCounterOp("c2", 3))},
311			{"doc-gset", crdtGSetBody("dev-1", crdtGSetOp("g1", "b", "a"))},
312			{"doc-gset", crdtGSetBody("dev-2", crdtGSetOp("g2", "c"))},
313			{"doc-register", crdtRegisterBody("dev-1", map[string]any{"id": "r1", "version": 1, "value": map[string]any{"k": true}})},
314			{"doc-register", crdtRegisterBody("dev-2", map[string]any{"id": "r2", "version": 2, "value": nil})},
315			{"doc-orset", crdtORSetBody("dev-1", crdtORSetOp("a1", "add", "apple"))},
316			{"doc-orset", crdtORSetBody("dev-2", crdtORSetOp("r1", "remove", "apple"))},
317		}
318		for _, step := range steps {
319			if w := submitCRDT(t, h, step.doc, step.body); w.Code != http.StatusOK {
320				t.Fatalf("submit %s: %s", step.doc, w.Body.String())
321			}
322			assertSame(t, step.doc)
323		}
324	
325		// The final bodies are the contract's exact shapes, register included.
326		if got := crdtStateBody(t, h, "doc-register"); got != `{"type":"register","value":null}`+"\n" {
327			t.Fatalf("register state = %q", got)
328		}
329		if got := crdtStateBody(t, h, "doc-orset"); got != `{"type":"orset","value":[]}`+"\n" {
330			t.Fatalf("orset state = %q", got)
331		}
332	}
333	
334	// Type fixation, idempotency and conflict judgments survive a restart for
335	// counter and register documents alike; the merged state is byte-identical.
336	func TestCRDTJudgmentsPersistAcrossRestart(t *testing.T) {
337		path := filepath.Join(t.TempDir(), "crdt-contract.db")
338		open := func(t *testing.T) (http.Handler, *app.App) {
339			t.Helper()
340			s, err := app.Open(path)
341			if err != nil {
342				t.Fatal(err)
343			}
344			return NewHandler(s), s
345		}
346	
347		h, s := open(t)
348		registerDevice(t, h, "dev-1")
349		registerDevice(t, h, "dev-2")
350		if w := submitCRDT(t, h, "cdoc", crdtCounterBody("dev-1", crdtCounterOp("c1", 5))); w.Code != http.StatusOK {
351			t.Fatal(w.Body.String())
352		}
353		if w := submitCRDT(t, h, "cdoc", crdtCounterBody("dev-2", crdtCounterOp("d1", 3))); w.Code != http.StatusOK {
354			t.Fatal(w.Body.String())
355		}
356		reg := func(id string, version int, value string) map[string]any {
357			return crdtRegisterBody("dev-1", map[string]any{"id": id, "version": version, "value": value})
358		}
359		if w := submitCRDT(t, h, "rdoc", reg("r1", 5, "five")); w.Code != http.StatusOK {
360			t.Fatal(w.Body.String())
361		}
362		counterBefore := crdtStateBody(t, h, "cdoc")
363		registerBefore := crdtStateBody(t, h, "rdoc")
364		_ = s.Close()
365	
366		h, s = open(t)
367		defer func() { _ = s.Close() }()
368	
369		// The merged states are byte-identical after the restart.
370		if got := crdtStateBody(t, h, "cdoc"); got != counterBefore {
371			t.Fatalf("counter state after restart = %q, want %q", got, counterBefore)
372		}
373		if got := crdtStateBody(t, h, "rdoc"); got != registerBefore {
374			t.Fatalf("register state after restart = %q, want %q", got, registerBefore)
375		}
376	
377		// Idempotent replays are still idempotent.
378		w := submitCRDT(t, h, "cdoc", crdtCounterBody("dev-1", crdtCounterOp("c1", 5)))
379		if _, created := postJSONResult(t, w); created {
380			t.Fatal("counter replay after restart must be created=false")
381		}
382		w = submitCRDT(t, h, "rdoc", reg("r1", 5, "five"))
383		if _, created := postJSONResult(t, w); created {
384			t.Fatal("register replay after restart must be created=false")
385		}
386	
387		// Regressions and stalls are still 409.
388		if w := submitCRDT(t, h, "cdoc", crdtCounterBody("dev-1", crdtCounterOp("c2", 4))); w.Code != http.StatusConflict {
389			t.Fatalf("counter regression after restart = %d, want 409", w.Code)
390		}
391		if w := submitCRDT(t, h, "rdoc", reg("r2", 4, "four")); w.Code != http.StatusConflict {
392			t.Fatalf("register regression after restart = %d, want 409", w.Code)
393		}
394		if w := submitCRDT(t, h, "rdoc", reg("r3", 5, "stall")); w.Code != http.StatusConflict {
395			t.Fatalf("register stall after restart = %d, want 409", w.Code)
396		}
397	
398		// Type fixation still holds on both documents.
399		if w := submitCRDT(t, h, "cdoc", crdtGSetBody("dev-1", crdtGSetOp("g1", "x"))); w.Code != http.StatusConflict {
400			t.Fatalf("gset on counter doc after restart = %d, want 409", w.Code)
401		}
402		if w := submitCRDT(t, h, "rdoc", crdtCounterBody("dev-1", crdtCounterOp("c9", 1))); w.Code != http.StatusConflict {
403			t.Fatalf("counter on register doc after restart = %d, want 409", w.Code)
404		}
405	
406		// And every rejection left the merged states untouched.
407		if got := crdtStateBody(t, h, "cdoc"); got != counterBefore {
408			t.Fatalf("counter state after rejections = %q, want %q", got, counterBefore)
409		}
410		if got := crdtStateBody(t, h, "rdoc"); got != registerBefore {
411			t.Fatalf("register state after rejections = %q, want %q", got, registerBefore)
412		}
413	}
