		return false
	}
	for i, seg := range segs {
		if seg != "query" {
			continue
		}
		// Identifier positions: sessionId (0) and documentId (2).
		if i == 0 || i == 2 {
			continue
		}
		// Endpoint keyword position: the sixth segment must be exactly "query"
		// with the documents/crdt scaffolding around it, and no segment may
		// follow. Any other occurrence is a malformed path.
		if i == 4 && len(segs) == 5 &&
