	}
	w, _ = postJSON(t, h, "/v1/documents/doc/crdt/ops", crdtCounterBody("dev-2", crdtCounterOp("a1", 5)))
	if w.Code != http.StatusConflict {
		t.Fatalf("other-device resubmit = %d, want 409", w.Code)
