14	)
15	
16	// crdtSubscribeURL builds the CRDT state subscription URL.
17	func crdtSubscribeURL(srv *httptest.Server, session, doc string) string {
18		return srv.URL + "/v1/sessions/" + session + "/documents/" + doc + "/crdt/state/subscribe"
19	}
20	
21	// readCRDTState reads the next complete text frame, validates the wire format
22	// (compact single-line JSON terminated by one newline, keys type then value)
23	// and decodes the state. Pongs are skipped; a close frame fails the test.
24	func (c *wsClient) readCRDTState() crdt.State {
25		c.t.Helper()
26		for {
27			fin, opcode, payload := c.readFrame()
28			switch opcode {
29			case wsOpcodeText:
30				if !fin {
31					c.t.Fatal("server sent a fragmented text frame")
32				}
33				if len(payload) == 0 || payload[len(payload)-1] != '\n' {
34					c.t.Fatalf("state frame is not newline-terminated: %q", payload)
35				}
36				line := string(payload[:len(payload)-1])
37				if strings.ContainsAny(line, "\r\n") {
38					c.t.Fatalf("state frame is not a single line: %q", payload)
39				}
40				if strings.Contains(line, ", ") || strings.Contains(line, ": ") {
41					c.t.Fatalf("state frame is not compact JSON: %q", payload)
42				}
43				var state crdt.State
44				if err := json.Unmarshal(payload, &state); err != nil {
45					c.t.Fatalf("text frame is not a crdt state: %s (%v)", payload, err)
46				}
47				return state
48			case wsOpcodePong:
49				continue
50			case wsOpcodeClose:
51				c.t.Fatalf("unexpected close frame while reading state: code=%d", closeCode(payload))
52			default:
53				c.t.Fatalf("unexpected opcode %d while reading state", opcode)
54			}
55		}
56	}
57	
58	// readCRDTRaw reads the raw payload bytes of the next text frame (newline
59	// included), pongs skipped.
60	func (c *wsClient) readCRDTRaw() []byte {
61		c.t.Helper()
62		for {
63			fin, opcode, payload := c.readFrame()
64			if opcode == wsOpcodePong {
65				continue
66			}
67			if opcode != wsOpcodeText || !fin {
68				c.t.Fatalf("unexpected opcode=%d fin=%v", opcode, fin)
69			}
70			return payload
71		}
72	}
73	
74	func crdtCounterOp(id string, value int) map[string]any {
75		return map[string]any{"id": id, "value": value}
76	}
77	
78	func crdtGSetOp(id string, elements ...string) map[string]any {
79		return map[string]any{"id": id, "elements": elements}
80	}
81	
82	func postCRDTOps(t *testing.T, srv *httptest.Server, doc string, body map[string]any) int {
83		t.Helper()
84		return postHTTP(t, srv, "/v1/documents/"+doc+"/crdt/ops", body)
85	}
86	
87	func crdtCounterValue(t *testing.T, state crdt.State) int64 {
88		t.Helper()
89		var n int64
90		if err := json.Unmarshal(state.Value, &n); err != nil {
91			t.Fatalf("counter value %s is not an integer: %v", state.Value, err)
92		}
93		return n
94	}
95	
96	func crdtSetElements(t *testing.T, state crdt.State) []string {
97		t.Helper()
98		var elements []string
99		if err := json.Unmarshal(state.Value, &elements); err != nil {
100			t.Fatalf("gset value %s is not a string array: %v", state.Value, err)
101		}
102		return elements
103	}
104	
105	// All pre-upgrade failures are ordinary JSON errors: no 101, no redirect and
106	// no HTML, and nothing about the session or state is leaked.
107	func TestCRDTSubscribePreUpgradeValidation(t *testing.T) {
108		h, _ := newTestHandler(t)
109		registerDevice(t, h, "dev-1")
110		w, _ := postJSON(t, h, "/v1/devices/dev-1/sessions", map[string]any{"sessionId": "sess"})
111		if w.Code != http.StatusOK {
112			t.Fatal(w.Body.String())
113		}
114		// Give doc2 a revoked permission so the 403 branch is reachable.
115		w, _ = postJSON(t, h, "/v1/documents/doc2/permissions", map[string]any{"deviceId": "dev-1", "action": "revoke"})
116		if w.Code != http.StatusOK {
117			t.Fatal(w.Body.String())
118		}
119	
120		base := "/v1/sessions/sess/documents/doc/crdt/state/subscribe"
121		cases := []struct {
122			name       string
123			method     string
124			target     string
125			upgrade    bool
126			wantStatus int
127		}{
128			{"no upgrade headers", http.MethodGet, base, false, http.StatusBadRequest},
129			{"wrong method", http.MethodPost, base, false, http.StatusBadRequest},
130			{"empty session segment", http.MethodGet, "/v1/sessions//documents/doc/crdt/state/subscribe", true, http.StatusBadRequest},
131			{"empty document segment", http.MethodGet, "/v1/sessions/sess/documents//crdt/state/subscribe", true, http.StatusBadRequest},
132			{"trailing slash", http.MethodGet, base + "/", true, http.StatusBadRequest},
133			{"extra segment", http.MethodGet, base + "/extra", true, http.StatusBadRequest},
134			{"missing state segment", http.MethodGet, "/v1/sessions/sess/documents/doc/crdt/subscribe", true, http.StatusBadRequest},
135			{"extra segment past state", http.MethodGet, "/v1/sessions/sess/documents/doc/crdt/state/extra", true, http.StatusBadRequest},
136			{"wrong terminal word", http.MethodGet, "/v1/sessions/sess/documents/doc/crdt/statex/subscribe", true, http.StatusBadRequest},
137			{"bare crdt namespace", http.MethodGet, "/v1/sessions/sess/documents/doc/crdt", true, http.StatusBadRequest},
138			{"unknown session", http.MethodGet, "/v1/sessions/ghost/documents/doc/crdt/state/subscribe", true, http.StatusNotFound},
139			{"revoked permission", http.MethodGet, "/v1/sessions/sess/documents/doc2/crdt/state/subscribe", true, http.StatusForbidden},
140			// Handshake shape is checked before the session lookup.
141			{"bad handshake before unknown session", http.MethodGet, "/v1/sessions/ghost/documents/doc/crdt/state/subscribe", false, http.StatusBadRequest},
142		}
143	
144		for _, tc := range cases {
145			t.Run(tc.name, func(t *testing.T) {
146				var r *http.Request
147				if tc.upgrade {
148					r = upgradeRequest(tc.target)
149				} else {
150					r = httptest.NewRequest(tc.method, tc.target, nil)
151				}
152				rec := httptest.NewRecorder()
153				h.ServeHTTP(rec, r)
154	
155				if rec.Code != tc.wantStatus {
156					t.Fatalf("status = %d, want %d, body = %s", rec.Code, tc.wantStatus, rec.Body.String())
157				}
158				if ct := rec.Header().Get("Content-Type"); ct != "application/json" {
159					t.Fatalf("content-type = %q, want application/json", ct)
160				}
161				var body map[string]string
162				if err := json.Unmarshal(rec.Body.Bytes(), &body); err != nil || body["error"] == "" {
163					t.Fatalf("body = %q, want a JSON error", rec.Body.String())
164				}
165			})
166		}
167	}
168	
169	// A malformed handshake over a real connection is a 400 JSON response.
170	func TestCRDTSubscribeBadHandshakeOverTCP(t *testing.T) {
171		srv, _ := newWSTestServer(t)
172		setupSession(t, srv, "dev-1", "sess", "doc", 0)
173		target := "/v1/sessions/sess/documents/doc/crdt/state/subscribe"
174	
175		cases := []struct {
176			name    string
177			headers []string
178		}{
179			{"missing connection upgrade", []string{
180				"Upgrade: websocket",
181				"Sec-WebSocket-Key: " + newWSKey(),
182				"Sec-WebSocket-Version: 13",
183			}},
184			{"wrong version", []string{
185				"Connection: Upgrade",
186				"Upgrade: websocket",
187				"Sec-WebSocket-Key: " + newWSKey(),
188				"Sec-WebSocket-Version: 8",
189			}},
190			{"bad key", []string{
191				"Connection: Upgrade",
192				"Upgrade: websocket",
193				"Sec-WebSocket-Key: nope",
194				"Sec-WebSocket-Version: 13",
195			}},
196		}
197		for _, tc := range cases {
198			t.Run(tc.name, func(t *testing.T) {
199				resp, conn := dialWSRaw(t, srv.URL, target, tc.headers...)
200				defer conn.Close()
201				if resp.StatusCode != http.StatusBadRequest {
202					t.Fatalf("status = %d, want 400", resp.StatusCode)
203				}
204				data, _ := io.ReadAll(resp.Body)
205				if !strings.Contains(string(data), `"error"`) {
206					t.Fatalf("body = %q, want JSON error", data)
207				}
208			})
209		}
210	}
211	
212	// After the upgrade the current merged counter state is pushed first, matching
213	// the state read endpoint's body byte for byte.
214	func TestCRDTSubscribeInitialCounterState(t *testing.T) {
215		srv, _ := newWSTestServer(t)
216		setupSession(t, srv, "dev-1", "sess", "doc", 0)
217		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 5))); code != http.StatusOK {
218			t.Fatalf("submit = %d", code)
219		}
220	
221		resp, _ := httpGet(t, srv, "/v1/documents/doc/crdt/state")
222		if resp != http.StatusOK {
223			t.Fatalf("state read = %d", resp)
224		}
225		stateBody := mustReadBody(t, srv, "/v1/documents/doc/crdt/state")
226	
227		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
228		if conn == nil {
229			t.Fatalf("status = %d, want 101", hs.StatusCode)
230		}
231		defer conn.close()
232	
233		raw := conn.readCRDTRaw()
234		if string(raw) != stateBody {
235			t.Fatalf("frame %q != state read body %q", raw, stateBody)
236		}
237		var state crdt.State
238		_ = json.Unmarshal(raw, &state)
239		if state.Type != "counter" || crdtCounterValue(t, state) != 5 {
240			t.Fatalf("initial state = %+v", state)
241		}
242	}
243	
244	// A document with a change log but no CRDT operation stays silent until its
245	// first state appears; the state read endpoint answers 404 in the meantime.
246	func TestCRDTSubscribeSilentUntilFirstState(t *testing.T) {
247		srv, _ := newWSTestServer(t)
248		setupSession(t, srv, "dev-1", "sess", "doc", 2)
249	
250		if code, _ := httpGet(t, srv, "/v1/documents/doc/crdt/state"); code != http.StatusNotFound {
251			t.Fatalf("state before ops = %d, want 404", code)
252		}
253	
254		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
255		if conn == nil {
256			t.Fatalf("status = %d, want 101", hs.StatusCode)
257		}
258		defer conn.close()
259	
260		conn.setReadDeadline(300 * time.Millisecond)
261		if _, _, _, ok := conn.readFrameMaybe(); ok {
262			t.Fatal("a frame arrived before the first crdt state")
263		}
264		conn.clearReadDeadline()
265	
266		if code := postCRDTOps(t, srv, "doc", crdtGSetBody("dev-1", crdtGSetOp("g1", "apple"))); code != http.StatusOK {
267			t.Fatalf("submit = %d", code)
268		}
269		state := conn.readCRDTState()
270		if state.Type != "gset" {
271			t.Fatalf("type = %q, want gset", state.Type)
272		}
273		if got := crdtSetElements(t, state); len(got) != 1 || got[0] != "apple" {
274			t.Fatalf("elements = %v, want [apple]", got)
275		}
276	}
277	
278	// Counter commits that advance the per-device maximum push immediately in
279	// commit order; idempotent repeats, equal-value new ops and rejected
280	// regressions change no state and push nothing.
281	func TestCRDTSubscribeCounterPushesOnlyRealChanges(t *testing.T) {
282		srv, _ := newWSTestServer(t)
283		setupSession(t, srv, "dev-1", "sess", "doc", 0)
284	
285		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
286		if conn == nil {
287			t.Fatalf("status = %d", hs.StatusCode)
288		}
289		defer conn.close()
290	
291		// First ever state: 5.
292		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 5))); code != http.StatusOK {
293			t.Fatalf("submit = %d", code)
294		}
295		if n := crdtCounterValue(t, conn.readCRDTState()); n != 5 {
296			t.Fatalf("frame = %d, want 5", n)
297		}
298	
299		// Idempotent repeat of the same id/value pushes nothing.
300		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 5))); code != http.StatusOK {
301			t.Fatalf("idempotent resubmit = %d", code)
302		}
303		// A new id carrying an equal contribution is accepted but moves no maximum.
304		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a2", 5))); code != http.StatusOK {
305			t.Fatalf("equal-value submit = %d", code)
306		}
307		conn.setReadDeadline(300 * time.Millisecond)
308		if _, _, _, ok := conn.readFrameMaybe(); ok {
309			t.Fatal("an idempotent/equal-value commit pushed a frame")
310		}
311		conn.clearReadDeadline()
312	
313		// A regression is a 409 and pushes nothing.
314		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a3", 4))); code != http.StatusConflict {
315			t.Fatalf("regression = %d, want 409", code)
316		}
317		// A wholly invalid batch is a 400 and pushes nothing.
318		if code := postCRDTOps(t, srv, "doc", map[string]any{"deviceId": "dev-1", "type": "counter", "ops": []any{}}); code != http.StatusBadRequest {
319			t.Fatalf("empty batch = %d, want 400", code)
320		}
321		conn.setReadDeadline(300 * time.Millisecond)
322		if _, _, _, ok := conn.readFrameMaybe(); ok {
323			t.Fatal("a rejected commit pushed a frame")
324		}
325		conn.clearReadDeadline()
326	
327		// An advancing contribution pushes the new sum.
328		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a4", 8))); code != http.StatusOK {
329			t.Fatalf("advance = %d", code)
330		}
331		if n := crdtCounterValue(t, conn.readCRDTState()); n != 8 {
332			t.Fatalf("frame = %d, want 8", n)
333		}
334	
335		// A second device adds its maximum to the sum.
336		registerDeviceViaHTTP(t, srv, "dev-2")
337		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-2", crdtCounterOp("b1", 3))); code != http.StatusOK {
338			t.Fatalf("dev-2 submit = %d", code)
339		}
340		if n := crdtCounterValue(t, conn.readCRDTState()); n != 11 {
341			t.Fatalf("frame = %d, want 11", n)
342		}
343	}
