385	// Every live subscriber on the document gets each change in commit order, and
386	// the sequence is strictly increasing; subscribers on another document get
387	// nothing.
388	func TestCRDTSubscribeFanoutAndCommitOrder(t *testing.T) {
389		srv, _ := newWSTestServer(t)
390		setupSession(t, srv, "dev-1", "sess-1", "doc", 0)
391	
392		conns := make([]*wsClient, 3)
393		for i := range conns {
394			c, hs := dialWS(t, crdtSubscribeURL(srv, "sess-1", "doc"))
395			if c == nil {
396				t.Fatalf("subscriber %d status = %d", i, hs.StatusCode)
397			}
398			conns[i] = c
399		}
400		defer func() {
401			for _, c := range conns {
402				c.close()
403			}
404		}()
405	
406		// Many devices each advance their own maximum concurrently; each commit
407		// moves the sum, so every subscriber observes a strictly increasing
408		// sequence ending at the total.
409		const devices = 8
410		const perDevice = 5
411		var wg sync.WaitGroup
412		start := make(chan struct{})
413		for d := 0; d < devices; d++ {
414			device := "dev-" + itoa(d)
415			// dev-1 is already registered (owns sess-1); register the rest.
416			if device != "dev-1" {
417				registerDeviceViaHTTP(t, srv, device)
418			}
419			wg.Add(1)
420			go func() {
421				defer wg.Done()
422				<-start
423				for v := 1; v <= perDevice; v++ {
424					code := postCRDTOps(t, srv, "doc", crdtCounterBody(device, crdtCounterOp(device+"-"+itoa(v), v)))
425					if code != http.StatusOK {
426						t.Errorf("submit %s %d = %d", device, v, code)
427						return
428					}
429				}
430			}()
431		}
432		close(start)
433		wg.Wait()
434	
435		wantTotal := int64(devices * perDevice)
436		for i, c := range conns {
437			var last int64
438			count := 0
439			c.setReadDeadline(5 * time.Second)
440			for {
441				state, ok := func() (crdt.State, bool) {
442					fin, opcode, payload, ok := c.readFrameMaybe()
443					if !ok {
444						return crdt.State{}, false
445					}
446					if opcode != wsOpcodeText || !fin {
447						t.Fatalf("subscriber %d unexpected opcode %d", i, opcode)
448					}
449					var st crdt.State
450					if err := json.Unmarshal(payload, &st); err != nil {
451						t.Fatalf("subscriber %d bad frame %s: %v", i, payload, err)
452					}
453					return st, true
454				}()
455				if !ok {
456					break
457				}
458				n := crdtCounterValue(t, state)
459				if n <= last {
460					t.Fatalf("subscriber %d non-increasing sequence: %d after %d", i, n, last)
461				}
462				last = n
463				count++
464				if n == wantTotal {
465					break
466				}
467			}
468			c.clearReadDeadline()
469			if last != wantTotal {
470				t.Fatalf("subscriber %d ended at %d, want %d (frames=%d)", i, last, wantTotal, count)
471			}
472		}
473	}
