604	// The connection is push-only: inbound data frames are discarded and cannot
605	// submit CRDT operations; ping is answered with pong and the stream continues.
606	func TestCRDTSubscribePushOnlyAndPingPong(t *testing.T) {
607		srv, st := newWSTestServer(t)
608		setupSession(t, srv, "dev-1", "sess", "doc", 0)
609		if code := postCRDTOps(t, srv, "doc", crdtCounterBody("dev-1", crdtCounterOp("a1", 1))); code != http.StatusOK {
610			t.Fatalf("submit = %d", code)
611		}
612	
613		conn, hs := dialWS(t, crdtSubscribeURL(srv, "sess", "doc"))
614		if conn == nil {
615			t.Fatalf("status = %d", hs.StatusCode)
616		}
617		defer conn.close()
618		if n := crdtCounterValue(t, conn.readCRDTState()); n != 1 {
619			t.Fatalf("initial = %d", n)
620		}
621	
622		conn.sendText(`{"deviceId":"dev-1","type":"counter","ops":[{"id":"forged","value":99}]}`)
623		conn.sendPing()
624	
625		conn.setReadDeadline(2 * time.Second)
626		sawPong := false
627		for {
628			fin, opcode, _, ok := conn.readFrameMaybe()
629			if !ok {
630				break
631			}
632			if opcode == wsOpcodePong && fin {
633				sawPong = true
634				break
635			}
636			if opcode == wsOpcodeText {
637				t.Fatal("the server pushed a state after a discarded client frame")
638			}
639		}
640		conn.clearReadDeadline()
641		if !sawPong {
642			t.Fatal("no pong received for the ping")
643		}
644	
645		// The forged op never reached the CRDT tables: value still 1, op id free.
646		state, err := st.GetCRDTState("doc")
647		if err != nil {
648			t.Fatal(err)
649		}
650		if string(state.Value) != "1" {
651			t.Fatalf("state = %s, want 1 (client frame was applied)", state.Value)
652		}
653		results, err := st.SubmitCRDTOps("doc", crdt.TypeCounter, []crdt.Op{
654			{ID: "forged", DeviceID: "dev-1", Value: json.RawMessage(`99`)},
655		})
656		if err != nil {
657			t.Fatalf("forged id should be free: %v", err)
658		}
659		if !results[0].Created {
660			t.Fatal("forged id already existed: a client frame was written")
661		}
662		if n := crdtCounterValue(t, conn.readCRDTState()); n != 99 {
663			t.Fatalf("frame after real submit = %d, want 99", n)
664		}
665	}
