		{"trailing content", "application/json", `{"deviceId":"dev","ids":["a"]} junk`},
		{"second json value", "application/json", `{"deviceId":"dev","ids":["a"]}{}`},
		{"missing ids", "application/json", `{"deviceId":"dev"}`},
		{"null ids", "application/json", `{"deviceId":"dev","ids":null}`},
